    """CatBoost using ordered target statistics on raw categoricals."""
    from catboost import CatBoostClassifier

    return CatBoostClassifier(
        iterations=iterations,
        depth=5,
        learning_rate=0.05,
        l2_leaf_reg=3.0,
        random_seed=seed,
        verbose=0,
        thread_count=2,
        cat_features=cat_indices,
    )


