    import lightgbm as lgb

    return lgb.LGBMClassifier(
        objective="binary",
        n_estimators=200,
        learning_rate=0.05,
        num_leaves=15,
        subsample=0.9,
        colsample_bytree=0.9,
        reg_lambda=0.5,
        random_state=seed,
        n_jobs=2,
